#!/usr/bin/env bash
# Build both legs of one wave-16 CHECKSIG cell.
#
#   build.sh <cell_dir> alive2|saw <key>
#
# <key> selects spec/equiv/findings/wave16/10-checksig-policy/tools/c_<key>.cpp
# and l_<key>.cpp.  The L leg is a reviewed transliteration of the Lean model
# (documented in its header); it is not generated by twin/gen.py.
#
# SAW lanes link a shared checker stub (stubs.cpp) into BOTH modules; Alive2
# lanes keep the checker as an external declaration in both modules.  Cells
# that never call the checker simply carry the unused stub.
set -euo pipefail

CELL_DIR="$1"; MODE="$2"; KEY="$3"
TOOLS="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$TOOLS" && while [ ! -f spec/equiv/contract/error_kind.h ]; do cd ..; done; pwd)"
BUILD="$CELL_DIR/build"
mkdir -p "$BUILD"

CXX=(/usr/bin/clang++-20 -std=c++17 -I "$TOOLS" -fno-discard-value-names
     -fno-strict-aliasing)
LLVM=/usr/lib/llvm-20/bin

if [ "$MODE" = "alive2" ]; then
  "${CXX[@]}" -O1 -S -emit-llvm "$TOOLS/c_${KEY}.cpp" -o "$BUILD/c_leaf.ll"
  "${CXX[@]}" -O1 -S -emit-llvm "$TOOLS/l_${KEY}.cpp" -o "$BUILD/l_leaf.ll"
  {
    printf 'mode=alive2 key=%s\n' "$KEY"
    printf 'clang=%s\n' "$(/usr/bin/clang++-20 --version | head -1)"
    printf 'llvm=%s\n' "$("$LLVM/llvm-extract" --version | head -1)"
    printf 'cell_common_sha256=%s\n' "$(sha256sum "$TOOLS/cell_common.h" | cut -d' ' -f1)"
    printf 'c_src_sha256=%s\n' "$(sha256sum "$TOOLS/c_${KEY}.cpp" | cut -d' ' -f1)"
    printf 'l_src_sha256=%s\n' "$(sha256sum "$TOOLS/l_${KEY}.cpp" | cut -d' ' -f1)"
    printf 'c_leaf_sha256=%s\n' "$(sha256sum "$BUILD/c_leaf.ll" | cut -d' ' -f1)"
    printf 'l_leaf_sha256=%s\n' "$(sha256sum "$BUILD/l_leaf.ll" | cut -d' ' -f1)"
  } > "$BUILD/build.txt"
else
  "${CXX[@]}" -O0 -c -emit-llvm "$TOOLS/c_${KEY}.cpp" -o "$BUILD/c_leaf.bc"
  "${CXX[@]}" -O0 -c -emit-llvm "$TOOLS/l_${KEY}.cpp" -o "$BUILD/l_leaf.bc"
  "${CXX[@]}" -O0 -c -emit-llvm "$TOOLS/stubs.cpp" -o "$BUILD/stubs.bc"
  "$LLVM/llvm-link" "$BUILD/c_leaf.bc" "$BUILD/stubs.bc" -o "$BUILD/c_leaf_saw.bc"
  "$LLVM/llvm-link" "$BUILD/l_leaf.bc" "$BUILD/stubs.bc" -o "$BUILD/l_leaf_saw.bc"
  "$LLVM/llvm-dis" "$BUILD/c_leaf_saw.bc" -o "$BUILD/c_leaf_saw.ll"
  "$LLVM/llvm-dis" "$BUILD/l_leaf_saw.bc" -o "$BUILD/l_leaf_saw.ll"
  {
    printf 'mode=saw key=%s\n' "$KEY"
    printf 'clang=%s\n' "$(/usr/bin/clang++-20 --version | head -1)"
    printf 'llvm=%s\n' "$("$LLVM/llvm-link" --version | head -1)"
    printf 'cell_common_sha256=%s\n' "$(sha256sum "$TOOLS/cell_common.h" | cut -d' ' -f1)"
    printf 'c_src_sha256=%s\n' "$(sha256sum "$TOOLS/c_${KEY}.cpp" | cut -d' ' -f1)"
    printf 'l_src_sha256=%s\n' "$(sha256sum "$TOOLS/l_${KEY}.cpp" | cut -d' ' -f1)"
    printf 'stubs_sha256=%s\n' "$(sha256sum "$TOOLS/stubs.cpp" | cut -d' ' -f1)"
    printf 'c_bc_sha256=%s\n' "$(sha256sum "$BUILD/c_leaf_saw.bc" | cut -d' ' -f1)"
    printf 'l_bc_sha256=%s\n' "$(sha256sum "$BUILD/l_leaf_saw.bc" | cut -d' ' -f1)"
  } > "$BUILD/build_saw.txt"
fi
printf 'root=%s\n' "$ROOT" >/dev/null
